-- UPDATE Cart
-- SET Status = CASE
--     WHEN ABS(RANDOM() % 2) = 0 THEN 'Delivered'
--     ELSE 'On the way'
-- END;



UPDATE Product
SET Average_Rating = (
    SELECT AVG(Rating)
    FROM Review
    WHERE Review.Product_ID = Product.Product_ID
    
)
WHERE Product_ID IN (SELECT DISTINCT Product_ID FROM Review);
